import { describe, it, expect, beforeEach, jest } from '@jest/globals';
import express from 'express';
import request from 'supertest';
import cookieParser from 'cookie-parser';
import { login, register } from '../../src/middleware/auth';
import { applySecurityMiddleware } from '../../src/middleware/security';
import { errorHandler } from '../../src/middleware/errorHandler';

// Mock dependencies
jest.mock('../../src/logger', () => ({
  default: {
    info: jest.fn(),
    warn: jest.fn(),
    error: jest.fn(),
    debug: jest.fn(),
  }
}));

jest.mock('../../src/prisma', () => ({
  prisma: {
    user: {
      findUnique: jest.fn(),
      create: jest.fn(),
      update: jest.fn(),
    }
  }
}));

import { prisma } from '../../src/prisma';

describe('Authentication Security', () => {
  let app: express.Application;

  beforeEach(() => {
    app = express();
    app.use(express.json());
    app.use(cookieParser());
    applySecurityMiddleware(app);
    
    // Set up auth routes
    app.post('/api/auth/login', login);
    app.post('/api/auth/register', register);
    
    // Add error handler
    app.use(errorHandler);

    // Reset mocks
    jest.clearAllMocks();
  });

  describe('Cookie Security', () => {
    it('should set secure cookie options for refresh token on login', async () => {
      const mockUser = {
        id: 1,
        email: 'test@example.com',
        password: '$2a$10$validhashedpassword',
        name: 'Test User',
        role: 'teacher',
      };

      (prisma.user.findUnique as jest.Mock).mockResolvedValue(mockUser);
      
      // bcryptjs is already mocked globally to return true for compare

      const response = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
        });

      expect(response.status).toBe(200);
      
      // Check cookie headers
      const cookies = response.headers['set-cookie'];
      expect(cookies).toBeDefined();
      
      const refreshTokenCookie = cookies.find((cookie: string) => 
        cookie.startsWith('refreshToken=')
      );
      
      expect(refreshTokenCookie).toBeDefined();
      expect(refreshTokenCookie).toContain('HttpOnly');
      expect(refreshTokenCookie).toContain('SameSite=Strict');
      expect(refreshTokenCookie).toContain('Path=/');
      expect(refreshTokenCookie).toContain('Max-Age=604800'); // 7 days
    });

    it('should set secure flag in production environment', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const mockUser = {
        id: 1,
        email: 'test@example.com',
        password: '$2a$10$validhashedpassword',
        name: 'Test User',
        role: 'teacher',
      };

      (prisma.user.findUnique as jest.Mock).mockResolvedValue(mockUser);

      const response = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
        });

      const cookies = response.headers['set-cookie'];
      const refreshTokenCookie = cookies?.find((cookie: string) => 
        cookie.startsWith('refreshToken=')
      );

      expect(refreshTokenCookie).toContain('Secure');

      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('Password Security', () => {
    it('should enforce strong password requirements on registration', async () => {
      const weakPasswords = [
        'short',           // Too short
        'alllowercase',    // No uppercase, numbers, or special chars
        'ALLUPPERCASE',    // No lowercase, numbers, or special chars
        'NoNumbers!',      // No numbers
        'NoSpecial123',    // No special characters
        'No Spaces123!',   // Contains spaces
      ];

      for (const password of weakPasswords) {
        const response = await request(app)
          .post('/api/auth/register')
          .send({
            email: 'test@example.com',
            password,
            name: 'Test User',
          });

        expect(response.status).toBe(400);
        expect(response.body.message).toContain('Password');
      }
    });

    it('should accept strong passwords', async () => {
      (prisma.user.findUnique as jest.Mock).mockResolvedValue(null);
      (prisma.user.create as jest.Mock).mockResolvedValue({
        id: 1,
        email: 'test@example.com',
        name: 'Test User',
        role: 'teacher',
      });

      const response = await request(app)
        .post('/api/auth/register')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
          name: 'Test User',
        });

      expect(response.status).toBe(201);
      expect(response.body.user).toBeDefined();
      expect(response.body.accessToken).toBeDefined();
    });
  });

  describe('Security Headers on Auth Endpoints', () => {
    it('should include security headers on auth responses', async () => {
      (prisma.user.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        email: 'test@example.com',
        password: '$2a$10$validhashedpassword',
        name: 'Test User',
        role: 'teacher',
      });

      const response = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
        });

      // Check security headers
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBe('1; mode=block');
      expect(response.headers['referrer-policy']).toBe('strict-origin-when-cross-origin');
    });
  });

  describe('Input Validation', () => {
    it('should sanitize email input', async () => {
      const response = await request(app)
        .post('/api/auth/login')
        .send({
          email: '  TEST@EXAMPLE.COM  ',
          password: 'ValidPass123!',
        });

      // Email should be trimmed and lowercased
      expect(prisma.user.findUnique).toHaveBeenCalledWith({
        where: { email: 'test@example.com' },
      });
    });

    it('should reject invalid email formats', async () => {
      const invalidEmails = [
        'notanemail',
        '@example.com',
        'test@',
        'test@.com',
        'test..test@example.com',
      ];

      for (const email of invalidEmails) {
        const response = await request(app)
          .post('/api/auth/register')
          .send({
            email,
            password: 'ValidPass123!',
            name: 'Test User',
          });

        expect(response.status).toBe(400);
        expect(response.body.message).toContain('email');
      }
    });

    it('should prevent XSS in user input', async () => {
      (prisma.user.findUnique as jest.Mock).mockResolvedValue(null);
      (prisma.user.create as jest.Mock).mockResolvedValue({
        id: 1,
        email: 'test@example.com',
        name: 'Test User',
        role: 'teacher',
      });

      const response = await request(app)
        .post('/api/auth/register')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
          name: '<script>alert("XSS")</script>Test User',
        });

      expect(response.status).toBe(201);
      
      // Check that the name was sanitized
      const createCall = (prisma.user.create as jest.Mock).mock.calls[0][0];
      expect(createCall.data.name).toBe('Test User');
    });
  });

  describe('Timing Attack Prevention', () => {
    it('should return consistent response times for invalid emails', async () => {
      // Test with non-existent user
      (prisma.user.findUnique as jest.Mock).mockResolvedValue(null);

      const response1 = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'nonexistent@example.com',
          password: 'SomePassword123!',
        });

      expect(response1.status).toBe(401);
      expect(response1.body.message).toBe('Invalid email or password');

      // Test with existing user but wrong password
      (prisma.user.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        email: 'test@example.com',
        password: '$2a$10$validhashedpassword',
        name: 'Test User',
        role: 'teacher',
      });

      const response2 = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'test@example.com',
          password: 'WrongPassword123!',
        });

      expect(response2.status).toBe(401);
      expect(response2.body.message).toBe('Invalid email or password');
    });
  });

  describe('Account Enumeration Prevention', () => {
    it('should not reveal whether email exists during password reset', async () => {
      // Test with existing user
      (prisma.user.findUnique as jest.Mock).mockResolvedValue({
        id: 1,
        email: 'existing@example.com',
        name: 'Test User',
      });

      const response1 = await request(app)
        .post('/api/auth/forgot-password')
        .send({ email: 'existing@example.com' });

      expect(response1.body.message).toBe('If the email exists, a reset link has been sent');

      // Test with non-existent user
      (prisma.user.findUnique as jest.Mock).mockResolvedValue(null);

      const response2 = await request(app)
        .post('/api/auth/forgot-password')
        .send({ email: 'nonexistent@example.com' });

      expect(response2.body.message).toBe('If the email exists, a reset link has been sent');
    });
  });

  describe('JWT Security', () => {
    it('should include proper JWT claims', async () => {
      const mockUser = {
        id: 1,
        email: 'test@example.com',
        password: '$2a$10$validhashedpassword',
        name: 'Test User',
        role: 'teacher',
      };

      (prisma.user.findUnique as jest.Mock).mockResolvedValue(mockUser);

      const response = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'test@example.com',
          password: 'ValidPass123!',
        });

      expect(response.status).toBe(200);
      expect(response.body.accessToken).toBeDefined();
      
      // Decode JWT to check claims (without verifying signature in test)
      const tokenParts = response.body.accessToken.split('.');
      const payload = JSON.parse(Buffer.from(tokenParts[1], 'base64').toString());
      
      expect(payload.userId).toBe('1');
      expect(payload.email).toBe('test@example.com');
      expect(payload.role).toBe('teacher');
      expect(payload.iss).toBe('teaching-engine');
      expect(payload.aud).toBe('teaching-engine-users');
      expect(payload.exp).toBeDefined();
      expect(payload.iat).toBeDefined();
    });
  });
});